class AgentsTableData extends DataClass implements Insertable<AgentsTableData> {
  /// Unique agent identifier.
  final String id;

  /// Short agent name. Unique per workspace (enforced by
  /// `idx_agents_workspace_name` unique index).
  final String name;

  /// Human-readable title.
  final String title;

  /// Path to the agent's markdown file.
  final String agentMdPath;

  /// Id of the workspace this agent belongs to.
  final String workspaceId;

  /// Id of the agent this one reports to, if any.
  final String? reportsTo;

  /// Comma-separated list of skills.
  final String skills;

  /// Optional persona description.
  final String? persona;

  /// System prompt override for the agent.
  final String? systemPrompt;

  /// Selected adapter identifier.
  final String? adapterId;

  /// Selected model identifier.
  final String? modelId;

  /// Whether strict identity checking is enabled.
  final bool strictMode;

  /// Reasoning effort level: low, medium, or high.
  final String? effort;

  /// Context window size in tokens.
  final int? contextSize;

  /// JSON-encoded sandbox `AgentCapabilities` snapshot for this agent.
  /// Empty string falls back to the user-level default at dispatch time.
  final String sandboxCapabilitiesJson;

  /// JSON-encoded per-agent command policy delta (deny/allow/prompt lists
  /// merged over the profile default). Empty string falls back to the
  /// mode-based default at dispatch time.
  final String commandPolicyJson;

  /// Agent role (e.g. 'ceo', 'coder', 'reviewer'). Null for legacy agents.
  final String? role;

  /// Monthly budget in US cents for this agent.
  final int monthlyBudgetCents;

  /// Per-agent silence-timeout override in minutes. Null falls back to the
  /// per-mode default at dispatch time.
  final int? silenceTimeoutMinutes;

  /// Maximum number of tasks this agent may work concurrently. Drives the
  /// presence workload model (running/queued/idle vs capacity).
  final int maxConcurrentTasks;

  /// Agent visibility: `workspace` (shared across the workspace) or `private`.
  final String visibility;

  /// Governance lifecycle status: `active`, `paused` (e.g. budget hard-stop),
  /// or `archived`.
  final String lifecycleStatus;

  /// Shared budget policy this agent draws from, if any. Null means the
  /// per-agent `monthlyBudgetCents` applies directly.
  final String? budgetPolicyId;

  /// Custom runtime profile backing this agent, if any. Null means the
  /// adapter's default launch configuration applies.
  final String? runtimeProfileId;

  /// Creation timestamp.
  final DateTime createdAt;
  const AgentsTableData({
    required this.id,
    required this.name,
    required this.title,
    required this.agentMdPath,
    required this.workspaceId,
    this.reportsTo,
    required this.skills,
    this.persona,
    this.systemPrompt,
    this.adapterId,
    this.modelId,
    required this.strictMode,
    this.effort,
    this.contextSize,
    required this.sandboxCapabilitiesJson,
    required this.commandPolicyJson,
    this.role,
    required this.monthlyBudgetCents,
    this.silenceTimeoutMinutes,
    required this.maxConcurrentTasks,
    required this.visibility,
    required this.lifecycleStatus,
    this.budgetPolicyId,
    this.runtimeProfileId,
    required this.createdAt,
  });
