class ChannelMessagesTableData extends DataClass
    implements Insertable<ChannelMessagesTableData> {
  /// Message id.
  final String id;

  /// Channel id.
  final String channelId;

  /// Conversation (stream) id inside the channel. Every channel has a `main`
  /// conversation whose id equals the channel id; parentheses get fresh ids.
  final String conversationId;

  /// Id of the agent or user that sent the message.
  final String senderId;

  /// Sender type.
  final String senderType;

  /// Content.
  final String content;

  /// Message type.
  final String messageType;

  /// Metadata.
  final String? metadata;

  /// Compacted.
  final bool compacted;

  /// Whether this message has been reverted (rolled back) and is therefore
  /// hidden from the live conversation. Reverted messages are kept (not
  /// deleted) so an `unrevert` can restore them.
  final bool reverted;

  /// When this message was reverted, in epoch milliseconds. All messages
  /// reverted in one operation share a timestamp, so `unrevert` can restore the
  /// most-recent batch. Null when not reverted.
  final int? revertedAt;

  /// Embedding vector for semantic retrieval (Float32List bytes).
  final Uint8List? embedding;

  /// Created at.
  final DateTime createdAt;
  const ChannelMessagesTableData({
    required this.id,
    required this.channelId,
    required this.conversationId,
    required this.senderId,
    required this.senderType,
    required this.content,
    required this.messageType,
    this.metadata,
    required this.compacted,
    required this.reverted,
    this.revertedAt,
    this.embedding,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['channel_id'] = Variable<String>(channelId);
    map['conversation_id'] = Variable<String>(conversationId);
    map['sender_id'] = Variable<String>(senderId);
    map['sender_type'] = Variable<String>(senderType);
    map['content'] = Variable<String>(content);
    map['message_type'] = Variable<String>(messageType);
    if (!nullToAbsent || metadata != null) {
      map['metadata'] = Variable<String>(metadata);
    }
    map['compacted'] = Variable<bool>(compacted);
