class OrchestrationsTableData extends DataClass
    implements Insertable<OrchestrationsTableData> {
  /// Unique orchestration id (UUID v4).
  final String id;

  /// Workspace scope.
  final String workspaceId;

  /// The anchor ticket the orchestration was opened against. Cascades to null
  /// if the ticket is deleted (the orchestration record survives for audit).
  final String? parentTicketId;

  /// Shared discussion channel for the orchestration.
  final String? channelId;

  /// Agent that produced (and revises) the proposal (the orchestrator).
  final String? orchestratorAgentId;

  /// Lifecycle status (see `OrchestrationStatus`).
  final String status;

  /// JSON-serialized `OrchestrationProposal`.
  final String proposalJson;

  /// Monotonic proposal revision (>= 1), bumped on each refine/edit.
  final int revision;

  /// The revision the user approved, if any.
  final int? approvedRevision;

  /// Generated pipeline template id, set on approval.
  final String? pipelineTemplateId;

  /// Pipeline run id, set when execution starts.
  final String? pipelineRunId;

  /// Team created for the orchestration.
  final String? teamId;

  /// Project created for the orchestration.
  final String? projectId;

  /// Estimated total cost in US cents (from the proposal budget).
  final int? estimatedCostCents;

  /// Hard spending limit in US cents; the budget guard cancels the run when
  /// rolled-up cost exceeds it.
  final int? maxCostCents;

  /// JSON array of agent ids hired specifically for this orchestration.
  final String hiredAgentIdsJson;

  /// JSON array of approved sub-ticket keys (PRD 17 §4 partial approval).
  /// Null = every node approved (the whole-plan approve path).
  final String? approvedNodeKeysJson;

  /// Error message when the orchestration failed.
  final String? errorMessage;

  /// Creation timestamp.
  final DateTime createdAt;

  /// Last mutation time.
  final DateTime updatedAt;

  /// When the orchestration reached a terminal state.
  final DateTime? completedAt;
  const OrchestrationsTableData({
    required this.id,
    required this.workspaceId,
    this.parentTicketId,
    this.channelId,
    this.orchestratorAgentId,
    required this.status,
    required this.proposalJson,
    required this.revision,
    this.approvedRevision,
    this.pipelineTemplateId,
    this.pipelineRunId,
    this.teamId,
    this.projectId,
    this.estimatedCostCents,
    this.maxCostCents,
    required this.hiredAgentIdsJson,
    this.approvedNodeKeysJson,
    this.errorMessage,
    required this.createdAt,
    required this.updatedAt,
    this.completedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['workspace_id'] = Variable<String>(workspaceId);
    if (!nullToAbsent || parentTicketId != null) {
      map['parent_ticket_id'] = Variable<String>(parentTicketId);
    }
    if (!nullToAbsent || channelId != null) {
      map['channel_id'] = Variable<String>(channelId);
    }
    if (!nullToAbsent || orchestratorAgentId != null) {
      map['orchestrator_agent_id'] = Variable<String>(orchestratorAgentId);
    }
    map['status'] = Variable<String>(status);
    map['proposal_json'] = Variable<String>(proposalJson);
    map['revision'] = Variable<int>(revision);
    if (!nullToAbsent || approvedRevision != null) {
      map['approved_revision'] = Variable<int>(approvedRevision);
    }
    if (!nullToAbsent || pipelineTemplateId != null) {
      map['pipeline_template_id'] = Variable<String>(pipelineTemplateId);
    }
    if (!nullToAbsent || pipelineRunId != null) {
      map['pipeline_run_id'] = Variable<String>(pipelineRunId);
    }
    if (!nullToAbsent || teamId != null) {
      map['team_id'] = Variable<String>(teamId);
    }
    if (!nullToAbsent || projectId != null) {
      map['project_id'] = Variable<String>(projectId);
    }
    if (!nullToAbsent || estimatedCostCents != null) {
      map['estimated_cost_cents'] = Variable<int>(estimatedCostCents);
    }
    if (!nullToAbsent || maxCostCents != null) {
      map['max_cost_cents'] = Variable<int>(maxCostCents);
    }
    map['hired_agent_ids_json'] = Variable<String>(hiredAgentIdsJson);
    if (!nullToAbsent || approvedNodeKeysJson != null) {
      map['approved_node_keys_json'] = Variable<String>(approvedNodeKeysJson);
    }
    if (!nullToAbsent || errorMessage != null) {
      map['error_message'] = Variable<String>(errorMessage);
    }
