  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['run_id'] = Variable<String>(runId);
    map['workspace_id'] = Variable<String>(workspaceId);
    map['segments_json'] = Variable<String>(segmentsJson);
    map['segment_count'] = Variable<int>(segmentCount);
    map['transcript_chars'] = Variable<int>(transcriptChars);
    if (!nullToAbsent || outcome != null) {
      map['outcome'] = Variable<String>(outcome);
    }
    map['complete'] = Variable<bool>(complete);
    map['started_at'] = Variable<DateTime>(startedAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  RunTranscriptsTableCompanion toCompanion(bool nullToAbsent) {
    return RunTranscriptsTableCompanion(
      runId: Value(runId),
      workspaceId: Value(workspaceId),
      segmentsJson: Value(segmentsJson),
      segmentCount: Value(segmentCount),
      transcriptChars: Value(transcriptChars),
      outcome: outcome == null && nullToAbsent
          ? const Value.absent()
          : Value(outcome),
      complete: Value(complete),
      startedAt: Value(startedAt),
